class ExerciseSchema:
    """Schema for creating an exercise with required fields and value constraints."""

    def __init__(self, name: str, description: str, difficulty_level: int):
        self.name = name  # Required, must be a non-empty string
        self.description = description  # Required, must be a non-empty string
        self.difficulty_level = difficulty_level  # Required, must be an integer between 1 and 5

    @property
    def is_valid(self) -> bool:
        return (
            isinstance(self.name, str)
            and len(self.name.strip()) > 0
            and isinstance(self.description, str)
            and len(self.description.strip()) > 0
            and isinstance(self.difficulty_level, int)
            and 1 <= self.difficulty_level <= 5
        )

